const VALOR_HORA = 180;

// ---------------------------------------------------------------- dados de exemplo (fictícios)
function semente() {
  const r = sorteio(20261105), esc1 = (l) => l[Math.floor(r() * l.length)], ent = (a, b) => a + Math.floor(r() * (b - a + 1));
  const modelos = [['Volkswagen', 'Gol 1.0'], ['Volkswagen', 'Polo TSI'], ['Fiat', 'Argo 1.3'], ['Fiat', 'Strada'], ['Chevrolet', 'Onix 1.0 Turbo'], ['Chevrolet', 'S10 2.8 Diesel'], ['Hyundai', 'HB20 1.0'], ['Hyundai', 'Creta 1.6'], ['Toyota', 'Corolla 2.0'], ['Toyota', 'Hilux 2.8'], ['Honda', 'Civic 2.0'], ['Jeep', 'Renegade 1.8'], ['Renault', 'Kwid'], ['Ford', 'Ranger 3.2']];
  const nomes = ['Antônio Carlos Reis', 'Bárbara Siqueira', 'Cláudio Meireles', 'Daniela Fonseca', 'Edson Batista', 'Fátima Rocha', 'Geraldo Neto', 'Hugo Martins', 'Ivone Pacheco', 'Jorge Albuquerque', 'Kleber Santana', 'Luciana Prates', 'Márcio Vilela', 'Neide Coutinho', 'Oscar Benício', 'Raquel Duarte', 'Sebastião Gomes', 'Tereza Amorim', 'Ulisses Barreto', 'Valéria Campos', 'Transportadora Rota Sul', 'Construtora Pilar'];
  const clientes = nomes.map((nome, i) => ({ id: `cl${i}`, nome, telefone: `(62) 9${ent(8100, 9899)}-${ent(1000, 9999)}`, doc: i >= 20 ? `${ent(10, 99)}.${ent(100, 999)}.${ent(100, 999)}/0001-${ent(10, 99)}` : `${ent(100, 999)}.${ent(100, 999)}.${ent(100, 999)}-${ent(10, 99)}`, email: `${normal(nome.split(' ')[0])}@email.com` }));
  const letras = 'ABCDEFGHJKLMNPRSTUVWXYZ';
  const veiculos = [];
  clientes.forEach((c, i) => { for (let k = 0; k < (i >= 20 ? 3 : i % 4 === 0 ? 2 : 1); k++) { const [marca, modelo] = esc1(i >= 20 ? [['Volkswagen', 'Delivery 11.180'], ['Fiat', 'Fiorino'], ['Chevrolet', 'S10 2.8 Diesel'], ['Ford', 'Ranger 3.2']] : modelos); const ano = ent(2012, 2024); veiculos.push({ id: `ve${veiculos.length}`, cliente: c.id, placa: `${esc1([...letras])}${esc1([...letras])}${esc1([...letras])}${ent(0, 9)}${esc1([...letras])}${ent(10, 99)}`, marca, modelo, ano, cor: esc1(['Prata', 'Branco', 'Preto', 'Cinza', 'Vermelho']), km: (2026 - ano) * ent(9000, 16000) + ent(0, 9000), ultima_revisao: null }); } });
  const pecas = [['Óleo 5W30 sintético (L)', 'OLE-5W30', 38, 62, 48, 20], ['Filtro de óleo', 'FIL-OL', 22, 45, 26, 10], ['Filtro de ar', 'FIL-AR', 28, 58, 14, 8], ['Filtro de combustível', 'FIL-CB', 32, 68, 9, 6], ['Filtro de cabine', 'FIL-CA', 25, 55, 11, 6], ['Pastilha de freio dianteira', 'PAS-DI', 85, 180, 7, 6], ['Disco de freio (par)', 'DIS-PR', 210, 420, 3, 2], ['Vela de ignição', 'VEL-IG', 24, 48, 32, 16], ['Correia dentada (kit)', 'COR-KT', 260, 520, 2, 2], ['Amortecedor dianteiro', 'AMO-DI', 320, 610, 4, 2], ['Bateria 60 Ah', 'BAT-60', 390, 620, 3, 2], ['Fluido de freio DOT 4', 'FLU-D4', 28, 55, 12, 6], ['Aditivo de radiador (L)', 'ADI-RD', 22, 45, 15, 6], ['Lâmpada H4', 'LAM-H4', 18, 40, 1, 6], ['Bieleta', 'BIE-01', 45, 98, 6, 4]]
    .map(([nome, codigo, custo, preco, estoque, minimo], i) => ({ id: `pc${i}`, nome, codigo, custo, preco, estoque, minimo }));
  const servicos = [['Troca de óleo e filtro', 0.5], ['Revisão completa', 2.5], ['Troca de pastilhas de freio', 1], ['Troca de discos e pastilhas', 1.8], ['Diagnóstico eletrônico (scanner)', 0.7], ['Alinhamento e balanceamento', 1], ['Troca de correia dentada', 3], ['Troca de amortecedores (par)', 2.5], ['Higienização do ar-condicionado', 0.8], ['Troca de velas', 0.6], ['Troca de bateria', 0.3], ['Suspensão: troca de bieletas', 0.8]].map(([nome, horas], i) => ({ id: `sv${i}`, nome, horas, preco: Math.round(horas * VALOR_HORA) }));
  const combos = [[0, [[0, 4], [1, 1]]], [1, [[0, 4], [1, 1], [2, 1], [3, 1], [4, 1], [7, 4]]], [2, [[5, 1]]], [3, [[5, 1], [6, 1]]], [4, []], [5, []], [6, [[8, 1]]], [7, [[9, 2]]], [8, [[4, 1]]], [9, [[7, 4]]], [10, [[10, 1]]], [11, [[14, 2]]]];
  const ordens = [];
  for (let i = 0; i < 400; i++) {
    const ve = i < 386 ? esc1(veiculos) : veiculos[((i - 386) * 2 + 1) % veiculos.length], ini = i < 386 ? -ent(6, 160) : -ent(0, 5);
    const etapa = i < 386 ? 'entregue' : ['entrada', 'entrada', 'orcamento', 'orcamento', 'aprovado', 'servico', 'servico', 'peca', 'pronto', 'pronto', 'orcamento', 'servico', 'entrada', 'pronto'][i - 386];
    const [svi, pcs] = esc1(combos), sv = servicos[svi];
    const itens = [{ tipo: 'servico', ref: sv.id, descricao: sv.nome, qtd: 1, preco: sv.preco, aprovado: true }, ...pcs.map(([pi, q]) => ({ tipo: 'peca', ref: pecas[pi].id, descricao: pecas[pi].nome, qtd: q, preco: pecas[pi].preco, custo: pecas[pi].custo, aprovado: true }))];
    if (r() < 0.35) { const ex = esc1(combos.slice(2)); const s2 = servicos[ex[0]]; itens.push({ tipo: 'servico', ref: s2.id, descricao: s2.nome, qtd: 1, preco: s2.preco, aprovado: etapa === 'orcamento' ? null : r() < 0.7, sugerido: true }); ex[1].forEach(([pi, q]) => itens.push({ tipo: 'peca', ref: pecas[pi].id, descricao: pecas[pi].nome, qtd: q, preco: pecas[pi].preco, custo: pecas[pi].custo, aprovado: etapa === 'orcamento' ? null : itens[itens.length - 1].aprovado, sugerido: true })); }
    if (etapa === 'orcamento' || etapa === 'entrada') itens.forEach((x) => { if (x.sugerido || etapa === 'entrada') x.aprovado = null; });
    const entrada = diaMais(ini), km = ve.km - ent(0, 3000) * (ini < -60 ? 1 : 0);
    const o = { id: `os${i}`, numero: 0, veiculo: ve.id, cliente: ve.cliente, km, etapa, mecanico: MECANICOS[i % 4][0], entrada, previsao: etapa === 'entregue' ? diaMais(ent(0, 3), entrada) : i % 6 === 0 ? diaMais(-1) : diaMais(ent(0, 3)), relato: esc1(['Barulho ao frear', 'Revisão dos 40 mil km', 'Luz da injeção acesa', 'Carro puxando para a direita', 'Troca de óleo', 'Ar-condicionado sem gelar', 'Barulho na suspensão dianteira', 'Carro não pega de manhã']), checklist: CHECK.filter(() => r() < 0.35), combustivel: esc1(['1/4', '1/2', '3/4', 'Cheio', 'Reserva']), itens, desconto: 0 };
    if (etapa === 'entregue') { o.entregue_em = diaMais(ent(0, 4), entrada); o.pago = true; o.forma = esc1(FORMAS); }
    if (etapa === 'peca') o.aguardando = 'Amortecedor dianteiro · chega amanhã';
    ordens.push(o);
    if (svi <= 1 && etapa === 'entregue' && (!ve.ultima_revisao || ve.ultima_revisao < o.entregue_em)) { ve.ultima_revisao = o.entregue_em; ve.km_revisao = km; }
  }
  ordens.sort((x, y) => x.entrada.localeCompare(y.entrada)).forEach((o, k) => { o.numero = 4200 + k; });
  const agendamentos = Array.from({ length: 9 }, (_, i) => { const ve = esc1(veiculos); return { id: `ag${i}`, veiculo: ve.id, cliente: ve.cliente, data: diaMais(ent(1, 6)), hora: esc1(['07:30', '08:00', '09:00', '10:30', '13:30', '15:00']), servico: esc1(['Revisão', 'Troca de óleo', 'Freios', 'Diagnóstico', 'Alinhamento']) }; });
  return { _cfg: { empresa: 'Auto Center Torque', endereco: 'Av. T-63, 1.450 · Setor Bueno · Goiânia/GO', cnpj: '18.552.430/0001-09', telefone: '(62) 3251-7700' }, clientes, veiculos, pecas, servicos, ordens, agendamentos };
}

// ---------------------------------------------------------------- regras
const ords = (a) => a.db.lista('ordens');
const veic = (a, id) => a.db.obter('veiculos', id);
const cli = (a, id) => a.db.obter('clientes', id);
const peca = (a, id) => a.db.obter('pecas', id);
const valendo = (o) => o.itens.filter((x) => x.aprovado !== false);
const totalOS = (o) => soma(valendo(o), (x) => x.qtd * x.preco) - (o.desconto || 0);
const nomeV = (v) => (v ? `${v.modelo} · ${v.placa}` : '—');
const etE = (o) => `<span class="et sem-ponto" style="background:color-mix(in srgb,${etp(o.etapa)[2]} 14%,var(--painel));color:${etp(o.etapa)[2]}">${etp(o.etapa)[1]}</span>`;
const revisaoVence = (v) => { if (!v.ultima_revisao) return null; const porData = diaMais(180, v.ultima_revisao), porKm = (v.km_revisao || v.km) + 10000; return { data: porData, km: porKm }; };
const precisaRevisao = (v) => { const r = revisaoVence(v); return r && (diasAte(r.data) <= 15 || v.km >= r.km - 500); };

const colecoes = {
  clientes: { singular: 'cliente', plural: 'clientes', campos: [{ nome: 'nome', rotulo: 'Nome / empresa', tipo: 'texto', obrigatorio: true, largo: true }, { nome: 'telefone', rotulo: 'WhatsApp', tipo: 'tel', obrigatorio: true }, { nome: 'doc', rotulo: 'CPF / CNPJ', tipo: 'texto' }, { nome: 'email', rotulo: 'E-mail', tipo: 'email' }] },
  veiculos: { singular: 'veículo', plural: 'veículos', campos: [{ nome: 'cliente', rotulo: 'Dono', tipo: 'relacao', colecao: 'clientes', obrigatorio: true }, { nome: 'placa', rotulo: 'Placa', tipo: 'texto', obrigatorio: true, max: 8 }, { nome: 'marca', rotulo: 'Marca', tipo: 'texto', obrigatorio: true }, { nome: 'modelo', rotulo: 'Modelo', tipo: 'texto', obrigatorio: true }, { nome: 'ano', rotulo: 'Ano', tipo: 'numero' }, { nome: 'cor', rotulo: 'Cor', tipo: 'texto' }, { nome: 'km', rotulo: 'Quilometragem', tipo: 'numero' }],
    antesDeSalvar: (d) => ({ ...d, placa: String(d.placa).toUpperCase().replace(/[^A-Z0-9]/g, '') }) },
  pecas: { singular: 'peça', genero: 'f', plural: 'peças', campos: [{ nome: 'nome', rotulo: 'Nome', tipo: 'texto', obrigatorio: true, largo: true }, { nome: 'codigo', rotulo: 'Código', tipo: 'texto' }, { nome: 'custo', rotulo: 'Custo', tipo: 'moeda' }, { nome: 'preco', rotulo: 'Preço de venda', tipo: 'moeda', obrigatorio: true }, { nome: 'estoque', rotulo: 'Estoque', tipo: 'numero', padrao: 0 }, { nome: 'minimo', rotulo: 'Mínimo', tipo: 'numero', padrao: 2 }] },
  servicos: { singular: 'serviço', plural: 'serviços', campos: [{ nome: 'nome', rotulo: 'Nome', tipo: 'texto', obrigatorio: true, largo: true }, { nome: 'horas', rotulo: 'Tempo padrão (horas)', tipo: 'numero', passo: '0.1' }, { nome: 'preco', rotulo: 'Preço da mão de obra', tipo: 'moeda', obrigatorio: true }] },
};

// ---------------------------------------------------------------- abrir OS (check-in do veículo)
async function checkin(a, base = {}) {
  const r = await modal({ titulo: 'Entrada de veículo', largura: 660, corpo: `<form class="form-grade">
    <label class="campo largo">Veículo<select name="v" required><option value="">Placa ou modelo…</option>${a.db.lista('veiculos').sort((x, y) => x.placa.localeCompare(y.placa)).map((v) => `<option value="${v.id}" ${v.id === base.veiculo ? 'selected' : ''}>${esc(v.placa)} · ${esc(v.marca)} ${esc(v.modelo)} · ${esc(cli(a, v.cliente)?.nome || '')}</option>`).join('')}</select></label>
    <label class="campo">Quilometragem atual<input name="km" type="number" min="0" required></label><label class="campo">Combustível<select name="comb">${['Reserva', '1/4', '1/2', '3/4', 'Cheio'].map((c) => `<option>${c}</option>`).join('')}</select></label>
    <label class="campo">Mecânico<select name="mec">${MECANICOS.map(([id, n]) => `<option value="${id}">${n}</option>`).join('')}</select></label><label class="campo">Previsão de entrega<input name="prev" type="date" value="${diaMais(1)}"></label>
    <label class="campo largo">O que o cliente relatou<textarea name="relato" required>${esc(base.relato || '')}</textarea></label>
    <fieldset class="campo largo" style="border:0;padding:0"><legend style="margin-bottom:6px">Checklist de entrada</legend><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:6px">${CHECK.map((c) => `<label class="flex" style="font-weight:400;color:var(--tx);gap:6px"><input type="checkbox" name="ck" value="${esc(c)}">${esc(c)}</label>`).join('')}</div></fieldset></form>`,
    aoAbrir: (f) => { const s = f.querySelector('[name=v]'), k = f.querySelector('[name=km]'); const pk = () => { const v = veic(a, s.value); if (v) k.value = v.km; }; s.addEventListener('change', pk); pk(); },
    botoes: [{ rotulo: 'Cancelar', valor: null, classe: 'fant' }, { rotulo: 'Abrir OS', classe: 'pri', acao: (f) => { const fm = f.querySelector('form'); if (!fm.reportValidity()) return false; return { ...Object.fromEntries(new FormData(fm)), ck: [...fm.querySelectorAll('[name=ck]:checked')].map((x) => x.value) }; } }] });
  if (!r) return null; const v = veic(a, r.v);
  if (Number(r.km) < v.km && !(await confirmar(`A quilometragem informada (${num(r.km)}) é menor que a última registrada (${num(v.km)}). Continuar?`))) return null;
  a.db.salvar('veiculos', { id: v.id, km: Math.max(v.km, Number(r.km)) });
  const o = a.db.salvar('ordens', { numero: Math.max(4000, ...ords(a).map((x) => x.numero)) + 1, veiculo: v.id, cliente: v.cliente, km: Number(r.km), etapa: 'entrada', mecanico: r.mec, entrada: hoje(), previsao: r.prev, relato: r.relato, checklist: r.ck, combustivel: r.comb, itens: [], desconto: 0 });
  a.db.registrar(`ordens:${o.id}`, 'Veículo deu entrada', { icone: 'sign-in' }); if (base.ag) a.db.apagar('agendamentos', base.ag);
  avisar(`OS #${o.numero} aberta · ${v.placa}`); a.render(); a.abrir('os', o.id); return o;
}

// ---------------------------------------------------------------- páginas
function painel(a) {
  const ab = ords(a).filter((o) => o.etapa !== 'entregue'), ym = hoje().slice(0, 7), ent = ords(a).filter((o) => o.etapa === 'entregue' && String(o.entregue_em).startsWith(ym));
  const dias = Array.from({ length: 30 }, (_, i) => diaMais(i - 29)), aguard = ab.filter((o) => o.etapa === 'orcamento');
  const rev = a.db.lista('veiculos').filter(precisaRevisao);
  const sug = ords(a).filter((o) => diasAte(o.entrada) > -90 && o.etapa === 'entregue').flatMap((o) => o.itens.filter((x) => x.sugerido));
  return `${kpis([{ rot: 'Carros no pátio', icone: 'car', val: num(ab.length), nota: `${ab.filter((o) => o.etapa === 'pronto').length} prontos · ${ab.filter((o) => o.previsao < hoje() && o.etapa !== 'pronto').length} atrasados` },
    { rot: `Faturado em ${nomeMes(ym)}`, icone: 'coins', val: moeda(soma(ent, totalOS)), spark: dias.map((d) => soma(ords(a).filter((o) => o.entregue_em === d), totalOS)) },
    { rot: 'Ticket médio', icone: 'receipt', val: moeda(soma(ent, totalOS) / (ent.length || 1)), nota: `${ent.length} OS entregues no mês` },
    { rot: 'Aprovação de orçamentos', icone: 'thumbs-up', val: pct((sug.filter((x) => x.aprovado).length / (sug.length || 1)) * 100), nota: 'serviços extras sugeridos (90 dias)' }])}
    <div class="grade g21"><div class="cartao"><div class="cartao-cab"><div><h3>Pátio agora</h3><div class="sub">${moeda(soma(ab, totalOS))} em serviços abertos</div></div><a class="btn peq" href="#/patio">Abrir pátio</a></div><div class="cartao-corpo">${barrasH(ETAPAS.slice(0, 6).map(([id, n, c]) => ({ html: `<span class="flex"><i style="width:9px;height:9px;border-radius:3px;background:${c}"></i>${n}</span>`, v: ab.filter((o) => o.etapa === id).length, extra: moedaC(soma(ab.filter((o) => o.etapa === id), totalOS)) })))}</div></div>
      <div class="cartao"><div class="cartao-cab"><div><h3>Orçamentos esperando o cliente</h3></div></div>${aguard.length ? `<ul class="lista">${aguard.map((o) => { const v = veic(a, o.veiculo), c = cli(a, o.cliente); return `<li class="clicavel" data-abrir="os:${o.id}"><div class="cresce"><div class="t corta">${esc(v?.modelo || '')} <span class="mono mute-2">${esc(v?.placa || '')}</span></div><div class="s corta">${esc(c?.nome || '')} · enviado ${relativo(o.entrada)}</div></div><b class="num">${moeda(totalOS(o))}</b></li>`; }).join('')}</ul>` : vazio('check-circle', 'Nenhum orçamento pendente')}</div></div>
    <div class="grade g2"><div class="cartao"><div class="cartao-cab"><div><h3>Revisões a vencer</h3><div class="sub">A cada 10 mil km ou 6 meses · chame o cliente antes do concorrente</div></div><a class="btn peq" href="#/revisoes">Ver todas</a></div>${rev.length ? `<ul class="lista">${rev.slice(0, 6).map((v) => { const c = cli(a, v.cliente), rv = revisaoVence(v); return `<li>${ic('car')}<div class="cresce"><div class="t corta">${esc(v.modelo)} <span class="mono mute-2">${esc(v.placa)}</span></div><div class="s corta">${esc(c?.nome || '')} · última ${relativo(v.ultima_revisao)} · vence ${dataCurta(rv.data)}</div></div><a class="btn peq" target="_blank" rel="noopener" href="${telLink(c?.telefone)}?text=${encodeURIComponent(`Olá, ${c?.nome.split(' ')[0]}! Aqui é da ${a.empresa}. A revisão do seu ${v.modelo} (${v.placa}) está chegando. Quer agendar? Temos horário esta semana.`)}">${ic('whatsapp-logo')}Lembrar</a></li>`; }).join('')}</ul>` : vazio('check-circle', 'Nenhuma revisão vencendo')}</div>
      <div class="cartao"><div class="cartao-cab"><div><h3>Serviços mais feitos</h3><div class="sub">Últimos 90 dias</div></div></div><div class="cartao-corpo">${barrasH(Object.entries(agrupar(ords(a).filter((o) => diasAte(o.entrada) > -90).flatMap((o) => o.itens.filter((x) => x.tipo === 'servico' && x.aprovado)), (x) => x.descricao)).map(([k, l]) => ({ rot: k, v: l.length, extra: moedaC(soma(l, (x) => x.preco)) })).sort((x, y) => y.v - x.v).slice(0, 7))}</div></div></div>`;
}

function patio(a) {
  a.kanbans.patio = (id, s) => { const o = a.db.obter('ordens', id); if (s === 'entregue' && !o.pago) { a.acoes.entregar({ id }); return; } if (['aprovado', 'servico'].includes(s) && o.itens.some((x) => x.aprovado == null)) { avisar('Ainda há itens do orçamento sem resposta do cliente', { tipo: 'erro' }); } a.db.salvar('ordens', { id, etapa: s }); a.db.registrar(`ordens:${id}`, etp(s)[1], { icone: 'arrow-right', tom: 'acc' }); avisar(`OS #${o.numero} → ${etp(s)[1]}`); if (s === 'pronto') a.acoes.avisarPronto({ id }); };
  a.kanbans['patio:abrir'] = (id) => a.abrir('os', id);
  return `<div class="entre"><span class="mute" style="font-size:12.5px">Arraste os carros conforme o serviço anda. Ao soltar em “Pronto”, o sistema prepara o aviso para o cliente.</span><button type="button" class="btn pri" data-acao="checkin">${ic('sign-in')}Entrada de veículo</button></div>`
    + kanban({ id: 'patio', itens: ords(a).filter((o) => o.etapa !== 'entregue' || diasAte(o.entregue_em) > -3), campo: 'etapa', colunas: ETAPAS.map(([id, nome, cor]) => ({ id, nome, cor, sub: (l) => moedaC(soma(l, totalOS)), classe: (o) => (o.etapa !== 'entregue' && o.etapa !== 'pronto' && o.previsao < hoje() ? 'parado' : '') })),
      ficha: (o) => { const v = veic(a, o.veiculo); return `<div class="entre"><span class="mono" style="font-size:12px;font-weight:600;background:var(--painel-2);padding:1px 6px;border-radius:4px;border:1px solid var(--borda)">${esc(v?.placa || '')}</span><span class="mute" style="font-size:11.5px">#${o.numero}</span></div><div class="t">${esc(v?.modelo || '')}</div><div class="s corta">${esc(cli(a, o.cliente)?.nome || '')} · ${esc(o.relato)}</div><div class="linha"><span class="flex" style="gap:5px">${av(nomeM(o.mecanico), 'p')}<span class="${o.etapa !== 'entregue' && o.previsao < hoje() ? 'er-tx' : 'mute'}" style="font-size:11.5px">${o.etapa === 'peca' ? 'aguardando peça' : dataCurta(o.previsao)}</span></span><b class="num" style="color:var(--tx)">${moedaC(totalOS(o))}</b></div>`; } });
}

function ordensPag(a) {
  return a.tab({ id: 'ordens', colecao: 'ordens', singular: 'OS', plural: 'OS', ordem: 'numero', desc: true, buscaDica: 'Placa, cliente, modelo ou nº da OS…', aoClicar: (id) => a.abrir('os', id), total: (l) => moeda(soma(l, totalOS)),
    visoes: [{ id: 'abertas', rot: 'No pátio', filtro: (o) => o.etapa !== 'entregue' }, { id: 'mes', rot: 'Entregues no mês', filtro: (o) => o.etapa === 'entregue' && String(o.entregue_em).startsWith(hoje().slice(0, 7)) }, { id: 'todas', rot: 'Todas' }],
    filtros: [{ k: 'etapa', rot: 'Etapa', opcoes: ETAPAS.map(([k, n]) => [k, n]) }, { k: 'mecanico', rot: 'Mecânico', opcoes: () => MECANICOS.map((m) => [m[0], m[1]]) }],
    textoBusca: (o) => { const v = veic(a, o.veiculo); return `${o.numero} ${v?.placa} ${v?.modelo} ${cli(a, o.cliente)?.nome}`; },
    colunas: [{ k: 'numero', rot: 'OS', render: (o) => `<span class="mono prim">#${o.numero}</span>` }, { k: 'veiculo', rot: 'Veículo', valor: (o) => nomeV(veic(a, o.veiculo)), render: (o) => `<span class="prim">${esc(veic(a, o.veiculo)?.modelo || '')}</span><span class="sub mono">${esc(veic(a, o.veiculo)?.placa || '')}</span>` }, { k: 'cliente', rot: 'Cliente', oc: true, valor: (o) => cli(a, o.cliente)?.nome }, { k: 'entrada', rot: 'Entrada', oc: true, render: (o) => dataCurta(o.entrada) }, { k: 'mecanico', rot: 'Mecânico', oc: true, valor: (o) => nomeM(o.mecanico) }, { k: 'total', rot: 'Total', n: true, valor: totalOS, render: (o) => moeda(totalOS(o)) }, { k: 'etapa', rot: 'Etapa', valor: (o) => ETAPAS.findIndex((e) => e[0] === o.etapa), render: etE, csv: (o) => etp(o.etapa)[1] }] });
}

function veiculosPag(a) {
  return a.tab({ id: 'veiculos', colecao: 'veiculos', singular: 'veículo', plural: 'veículos', ordem: 'placa', buscaDica: 'Placa, modelo ou dono…', novo: { rot: 'Novo veículo', attrs: 'data-acao="novoCad" data-c="veiculos"' }, aoClicar: (id) => a.abrir('veiculo', id),
    textoBusca: (v) => `${v.placa} ${v.marca} ${v.modelo} ${cli(a, v.cliente)?.nome}`,
    colunas: [{ k: 'placa', rot: 'Placa', render: (v) => `<span class="mono prim" style="font-weight:600">${esc(v.placa)}</span>` }, { k: 'modelo', rot: 'Veículo', render: (v) => `<span class="prim">${esc(v.marca)} ${esc(v.modelo)}</span><span class="sub">${v.ano} · ${esc(v.cor || '')}</span>` }, { k: 'cliente', rot: 'Dono', valor: (v) => cli(a, v.cliente)?.nome }, { k: 'km', rot: 'Km', n: true, render: (v) => num(v.km) }, { k: 'ultima', rot: 'Última revisão', oc: true, valor: (v) => v.ultima_revisao || '', render: (v) => (v.ultima_revisao ? `<span class="${precisaRevisao(v) ? 'al-tx' : ''}">${relativo(v.ultima_revisao)}</span>` : '<span class="mute">—</span>') }, { k: 'gasto', rot: 'Gasto total', n: true, valor: (v) => soma(ords(a).filter((o) => o.veiculo === v.id && o.etapa === 'entregue'), totalOS), render: (v) => moeda(soma(ords(a).filter((o) => o.veiculo === v.id && o.etapa === 'entregue'), totalOS)) }] });
}

function revisoes(a) {
  const vs = a.db.lista('veiculos').filter((v) => v.ultima_revisao).sort((x, y) => revisaoVence(x).data.localeCompare(revisaoVence(y).data));
  return `<div class="dica">${ic('info')}<span>O sistema calcula a próxima revisão pelo que vencer primeiro: 10.000 km ou 6 meses depois da última. Mande o lembrete e transforme em agendamento.</span></div>
    ${a.tab({ id: 'rev', itens: () => vs, singular: 'veículo', plural: 'veículos', aoClicar: (id) => a.abrir('veiculo', id),
      visoes: [{ id: 'vencendo', rot: 'Vencendo (15 dias)', filtro: precisaRevisao }, { id: 'proximas', rot: 'Próximos 60 dias', filtro: (v) => diasAte(revisaoVence(v).data) <= 60 }, { id: 'todos', rot: 'Todos' }],
      colunas: [{ k: 'placa', rot: 'Veículo', render: (v) => `<span class="prim">${esc(v.modelo)}</span><span class="sub mono">${esc(v.placa)}</span>` }, { k: 'cliente', rot: 'Dono', valor: (v) => cli(a, v.cliente)?.nome }, { k: 'ultima_revisao', rot: 'Última', render: (v) => dataCurta(v.ultima_revisao) }, { k: 'vence', rot: 'Vence em', valor: (v) => revisaoVence(v).data, render: (v) => `<span class="${precisaRevisao(v) ? 'er-tx' : ''}">${dataCurta(revisaoVence(v).data)}</span><span class="sub">ou aos ${num(revisaoVence(v).km)} km</span>` },
        { k: 'acao', rot: '', ord: false, csv: false, render: (v) => { const c = cli(a, v.cliente); return `<span class="flex" style="gap:6px;justify-content:flex-end"><a class="btn peq" target="_blank" rel="noopener" href="${telLink(c?.telefone)}?text=${encodeURIComponent(`Olá, ${c?.nome.split(' ')[0]}! Aqui é da ${a.empresa}. A revisão do seu ${v.modelo} (${v.placa}) vence em ${dataBR(revisaoVence(v).data)}. Quer agendar?`)}">${ic('whatsapp-logo')}Lembrar</a><button type="button" class="btn peq" data-acao="agendar" data-v="${v.id}">${ic('calendar-plus')}Agendar</button></span>`; } }] })}`;
}

function agenda(a) {
  const ags = a.db.lista('agendamentos').sort((x, y) => (x.data + x.hora).localeCompare(y.data + y.hora)), dias = [...new Set(ags.map((x) => x.data))];
  return `<div class="entre"><span class="mute" style="font-size:12.5px">Carros agendados para os próximos dias. Na chegada, clique em “Deu entrada” para abrir a OS.</span><button type="button" class="btn pri" data-acao="agendar">${ic('calendar-plus')}Agendar</button></div>
    ${dias.length ? dias.map((d) => `<div class="cartao"><div class="cartao-cab"><h3>${DIAS[paraData(d).getDay()]}, ${dataCurta(d)} <span class="mute">${relativo(d)}</span></h3></div><ul class="lista">${ags.filter((x) => x.data === d).map((x) => { const v = veic(a, x.veiculo), c = cli(a, x.cliente); return `<li><b class="num" style="width:48px">${x.hora}</b><div class="cresce"><div class="t">${esc(v?.modelo || '')} <span class="mono mute-2">${esc(v?.placa || '')}</span></div><div class="s">${esc(c?.nome || '')} · ${esc(x.servico)}</div></div><a class="btn peq fant ic-so" target="_blank" rel="noopener" href="${telLink(c?.telefone)}?text=${encodeURIComponent(`Olá, ${c?.nome.split(' ')[0]}! Confirmando seu horário na ${a.empresa}: ${dataBR(x.data)} às ${x.hora} (${x.servico}).`)}" aria-label="Confirmar no WhatsApp">${ic('whatsapp-logo')}</a><button type="button" class="btn peq" data-acao="deuEntrada" data-id="${x.id}">${ic('sign-in')}Deu entrada</button></li>`; }).join('')}</ul></div>`).join('') : vazio('calendar-blank', 'Nenhum agendamento')}`;
}

function estoque(a) {
  const st = a.estado.est ||= { aba: 'pecas' }, ps = a.db.lista('pecas');
  const abas = `<div class="abas-pag"><button type="button" data-acao="abaEst" data-a="pecas" aria-selected="${st.aba === 'pecas'}">${ic('package')}Peças</button><button type="button" data-acao="abaEst" data-a="servicos" aria-selected="${st.aba === 'servicos'}">${ic('wrench')}Serviços e mão de obra</button></div>`;
  if (st.aba === 'servicos') return `${abas}<div class="dica">${ic('info')}<span>Valor da hora técnica: <b>${moeda(VALOR_HORA)}</b>. O preço de cada serviço segue o tempo padrão.</span></div>` + a.tab({ id: 'servicos', colecao: 'servicos', singular: 'serviço', plural: 'serviços', ordem: 'nome', novo: { rot: 'Novo serviço', attrs: 'data-acao="novoCad" data-c="servicos"' }, aoClicar: async (id) => { if (await editar(a, 'servicos', a.db.obter('servicos', id))) a.render(); }, colunas: [{ k: 'nome', rot: 'Serviço', render: (s) => `<span class="prim">${esc(s.nome)}</span>` }, { k: 'horas', rot: 'Tempo padrão', n: true, render: (s) => `${num(s.horas, 1)} h` }, { k: 'preco', rot: 'Mão de obra', n: true, render: (s) => moeda(s.preco) }] });
  return abas + kpis([{ rot: 'Valor em estoque', icone: 'package', val: moeda(soma(ps, (p) => p.custo * p.estoque)) }, { rot: 'Abaixo do mínimo', icone: 'warning', val: num(ps.filter((p) => p.estoque <= p.minimo).length), alerta: ps.some((p) => p.estoque <= p.minimo) }, { rot: 'Margem média nas peças', icone: 'percent', val: pct((soma(ps, (p) => (p.preco - p.custo) / p.preco) / (ps.length || 1)) * 100) }])
    + a.tab({ id: 'pecas', colecao: 'pecas', singular: 'peça', plural: 'peças', ordem: 'nome', novo: { rot: 'Nova peça', attrs: 'data-acao="novoCad" data-c="pecas"' }, aoClicar: async (id) => { if (await editar(a, 'pecas', peca(a, id))) a.render(); },
      visoes: [{ id: 'todas', rot: 'Todas' }, { id: 'comprar', rot: 'Comprar', filtro: (p) => p.estoque <= p.minimo }],
      colunas: [{ k: 'nome', rot: 'Peça', render: (p) => `<span class="prim">${esc(p.nome)}</span><span class="sub mono">${esc(p.codigo)}</span>` }, { k: 'custo', rot: 'Custo', n: true, oc: true, render: (p) => moeda(p.custo) }, { k: 'preco', rot: 'Venda', n: true, render: (p) => moeda(p.preco) }, { k: 'estoque', rot: 'Estoque', n: true, render: (p) => (p.estoque <= p.minimo ? et(`${p.estoque} · mín. ${p.minimo}`, 'er') : `${p.estoque} un.`) }, { k: 'acao', rot: '', ord: false, csv: false, render: (p) => `<button type="button" class="btn peq" data-acao="entradaPeca" data-id="${p.id}">${ic('plus')}Entrada</button>` }] });
}

function relatorios(a) {
  const ent = ords(a).filter((o) => o.etapa === 'entregue' && diasAte(o.entregue_em) > -90), meses = Array.from({ length: 5 }, (_, i) => mesMais(i - 4));
  const mo = (o) => soma(valendo(o).filter((x) => x.tipo === 'servico'), (x) => x.qtd * x.preco), pc = (o) => soma(valendo(o).filter((x) => x.tipo === 'peca'), (x) => x.qtd * x.preco), lucroPc = (o) => soma(valendo(o).filter((x) => x.tipo === 'peca'), (x) => x.qtd * (x.preco - (x.custo || 0)));
  return `${kpis([{ rot: 'OS entregues (90 dias)', icone: 'wrench', val: num(ent.length) }, { rot: 'Mão de obra', icone: 'user-gear', val: moeda(soma(ent, mo)) }, { rot: 'Peças vendidas', icone: 'package', val: moeda(soma(ent, pc)), nota: `lucro de ${moeda(soma(ent, lucroPc))}` }, { rot: 'Tempo médio no pátio', icone: 'hourglass', val: `${num(soma(ent, (o) => diasEntre(o.entrada, o.entregue_em)) / (ent.length || 1), 1)} dias` }])}
    <div class="grade g2"><div class="cartao"><div class="cartao-cab"><div><h3>Faturamento por mês</h3></div></div><div class="cartao-corpo">${barras({ dados: meses.map((m) => { const l = ords(a).filter((o) => o.etapa === 'entregue' && String(o.entregue_em).startsWith(m)); return { rot: nomeMes(m), v: [soma(l, mo), soma(l, pc)] }; }), series: [{ nome: 'Mão de obra', cor: 'var(--acc)' }, { nome: 'Peças', cor: '#94a3b8' }], empilhado: true, fmt: moedaC, altura: 210 })}</div></div>
      <div class="cartao"><div class="cartao-cab"><div><h3>Produtividade dos mecânicos</h3><div class="sub">Últimos 90 dias</div></div></div><div class="tabela-caixa"><table class="tabela"><thead><tr><th>Mecânico</th><th class="n">OS</th><th class="n">Horas vendidas</th><th class="n">Mão de obra</th><th class="n">Comissão</th></tr></thead><tbody>${MECANICOS.map(([id, n, c]) => { const l = ent.filter((o) => o.mecanico === id); const h = soma(l.flatMap((o) => valendo(o).filter((x) => x.tipo === 'servico')), (x) => a.db.obter('servicos', x.ref)?.horas || 0); return `<tr><td><span class="flex">${av(n, 'p')}${esc(n)}</span></td><td class="n">${l.length}</td><td class="n">${num(h, 1)} h</td><td class="n">${moeda(soma(l, mo))}</td><td class="n">${moeda((soma(l, mo) * c) / 100)} <span class="mute">(${c}%)</span></td></tr>`; }).join('')}</tbody></table></div></div></div>
    <div class="cartao"><div class="cartao-cab"><div><h3>Marcas atendidas</h3></div></div><div class="cartao-corpo">${barrasH(Object.entries(agrupar(ent, (o) => veic(a, o.veiculo)?.marca || '—')).map(([m, l]) => ({ rot: m, v: l.length, extra: moedaC(soma(l, totalOS)) })).sort((x, y) => y.v - x.v))}</div></div>`;
}

// ---------------------------------------------------------------- documentos
function docOS(a, o) {
  const v = veic(a, o.veiculo), c = cli(a, o.cliente), cfg = a.db.cfg;
  return `<div class="doc"><div class="entre" style="align-items:flex-start"><div><h1>${esc(a.empresa)}</h1><div style="color:#555">${esc(cfg.endereco)} · ${esc(cfg.telefone)} · CNPJ ${esc(cfg.cnpj)}</div></div><div style="text-align:right"><b style="font-size:16px">OS #${o.numero}</b><div style="color:#555">${o.etapa === 'orcamento' || o.etapa === 'entrada' ? 'Orçamento' : 'Ordem de serviço'}</div></div></div>
    <h2>Cliente e veículo</h2><table><tr><td>${esc(c?.nome || '')}</td><td>${esc(c?.telefone || '')}</td><td>${esc(c?.doc || '')}</td></tr><tr><td><b>${esc(v?.marca || '')} ${esc(v?.modelo || '')} ${v?.ano || ''}</b></td><td>Placa <b>${esc(v?.placa || '')}</b></td><td>${num(o.km)} km · combustível ${esc(o.combustivel || '')}</td></tr><tr><td colspan="3">Relato: ${esc(o.relato)}</td></tr><tr><td colspan="3">Checklist de entrada: ${o.checklist?.length ? o.checklist.map(esc).join(' · ') : 'sem observações'}</td></tr></table>
    <h2>Serviços e peças</h2><table><thead><tr><th>Descrição</th><th class="n">Qtd.</th><th class="n">Unitário</th><th class="n">Total</th></tr></thead><tbody>${valendo(o).map((i) => `<tr><td>${esc(i.descricao)}</td><td class="n">${i.qtd}</td><td class="n">${moeda(i.preco)}</td><td class="n">${moeda(i.qtd * i.preco)}</td></tr>`).join('')}${o.desconto ? `<tr><td colspan="3">Desconto</td><td class="n">− ${moeda(o.desconto)}</td></tr>` : ''}<tr><td colspan="3"><b>Total</b></td><td class="n"><b>${moeda(totalOS(o))}</b></td></tr></tbody></table>
    <div style="margin-top:10px;color:#444;font-size:11px">Entrada ${dataBR(o.entrada)} · previsão ${dataBR(o.previsao)} · mecânico ${esc(nomeM(o.mecanico))}. Garantia de 90 dias para serviços e conforme o fabricante para peças. Veículos não retirados em 5 dias após o aviso de conclusão estão sujeitos a taxa de pátio.</div><div class="ass"><div>${esc(a.empresa)}</div><div>${esc(c?.nome || 'Cliente')}</div></div></div>`;
}

// ---------------------------------------------------------------- fichas
const fichas = {
  os(a, id, aba = 'itens') {
    const o = a.db.obter('ordens', id); if (!o) return null; const v = veic(a, o.veiculo), c = cli(a, o.cliente), i = ETAPAS.findIndex((e) => e[0] === o.etapa), pend = o.itens.filter((x) => x.aprovado == null);
    let corpo = '';
    if (aba === 'itens') corpo = `<div class="gav-sec">${o.itens.length ? `<table class="tabela"><thead><tr><th>Descrição</th><th class="n">Qtd.</th><th class="n">Total</th><th>Cliente</th><th></th></tr></thead><tbody>${o.itens.map((x, k) => `<tr style="${x.aprovado === false ? 'opacity:.5;text-decoration:line-through' : ''}"><td>${ic(x.tipo === 'peca' ? 'package' : 'wrench', 'p')} ${esc(x.descricao)}${x.sugerido ? ' <span class="et sem-ponto info" style="font-size:10.5px">sugerido</span>' : ''}</td><td class="n">${x.qtd}</td><td class="n">${moeda(x.qtd * x.preco)}</td><td>${x.aprovado === true ? et('Aprovado', 'ok') : x.aprovado === false ? et('Recusado', '') : `<span class="flex" style="gap:4px"><button type="button" class="btn peq ok" data-acao="aprovar" data-id="${id}" data-i="${k}" data-v="1" aria-label="Aprovar">${ic('check')}</button><button type="button" class="btn peq" data-acao="aprovar" data-id="${id}" data-i="${k}" data-v="0" aria-label="Recusar">${ic('x')}</button></span>`}</td><td class="acoes">${o.etapa !== 'entregue' ? `<button type="button" class="btn fant peq ic-so" data-acao="tirarItem" data-id="${id}" data-i="${k}" aria-label="Remover">${ic('trash')}</button>` : ''}</td></tr>`).join('')}</tbody><tfoot>${o.desconto ? `<tr><td colspan="2">Desconto</td><td class="n">− ${moeda(o.desconto)}</td><td colspan="2"></td></tr>` : ''}<tr><td colspan="2">Total aprovado</td><td class="n">${moeda(totalOS(o))}</td><td colspan="2"></td></tr></tfoot></table>` : vazio('wrench', 'Orçamento vazio', 'Adicione os serviços e as peças após o diagnóstico.')}
      ${o.etapa !== 'entregue' ? `<div class="flex" style="margin-top:12px;flex-wrap:wrap"><button type="button" class="btn" data-acao="addItem" data-id="${id}" data-t="servico">${ic('wrench')}Serviço</button><button type="button" class="btn" data-acao="addItem" data-id="${id}" data-t="peca">${ic('package')}Peça</button><button type="button" class="btn" data-acao="descontoOS" data-id="${id}">${ic('percent')}Desconto</button></div>` : ''}</div>`;
    if (aba === 'veiculo') corpo = `<div class="gav-sec">${props([['car', 'Veículo', `<a href="#" data-abrir="veiculo:${v?.id}">${esc(v?.marca || '')} ${esc(v?.modelo || '')} ${v?.ano || ''}</a>`], ['identification-card', 'Placa', `<span class="mono">${esc(v?.placa || '')}</span>`], ['gauge', 'Km na entrada', num(o.km)], ['gas-pump', 'Combustível', esc(o.combustivel || '')], ['chat-circle', 'Relato do cliente', esc(o.relato)], ['list-checks', 'Checklist', o.checklist?.length ? o.checklist.map((x) => et(x, 'al', 'sem-ponto')).join(' ') : 'sem observações'], ['user-gear', 'Mecânico', esc(nomeM(o.mecanico))], ['calendar-blank', 'Entrada / previsão', `${dataCurta(o.entrada)} → <span class="${o.etapa !== 'entregue' && o.previsao < hoje() ? 'er-tx' : ''}">${dataCurta(o.previsao)}</span>`], o.aguardando ? ['hourglass', 'Aguardando', esc(o.aguardando)] : null])}</div>`;
    if (aba === 'fotos') corpo = `${a.anexos.html('ordens', id, { titulo: 'Fotos do carro e das peças', dica: 'Fotografe as avarias na entrada e as peças trocadas. Elas aparecem para o cliente no link da OS.' })}<div class="gav-sec"><button type="button" class="btn" data-acao="linkOS" data-id="${id}">${ic('link')}Mandar o link com as fotos</button></div>`;
    if (aba === 'hist') corpo = `<div class="gav-sec">${linhaDoTempo([...a.db.historico(`ordens:${id}`).map((h) => ({ quando: h.quando, icone: h.icone, tom: h.tom, html: esc(h.texto) })), { quando: o.entrada, icone: 'sign-in', html: 'Entrada do veículo' }, ...(o.entregue_em ? [{ quando: o.entregue_em, icone: 'seal-check', tom: 'ok', html: `Entregue · ${esc(o.forma || '')}` }] : [])].sort((x, y) => String(y.quando).localeCompare(String(x.quando))))}</div>`;
    const prox = { entrada: ['orcamento', 'Enviar orçamento', 'paper-plane-tilt'], aprovado: ['servico', 'Iniciar serviço', 'play'], servico: ['pronto', 'Marcar como pronto', 'seal-check'], peca: ['servico', 'Peça chegou', 'package'] }[o.etapa];
    return { html: ficha({ tipo: 'Ordem de serviço', icone: 'wrench', titulo: `#${o.numero} · ${esc(v?.modelo || '')} <span class="mono" style="font-size:13px;color:var(--tx-2)">${esc(v?.placa || '')}</span>`, avatar: av(c?.nome || '?', 'g'), sub: `<span>${esc(c?.nome || '')}</span><b class="num" style="color:var(--tx)">· ${moeda(totalOS(o))}</b>${pend.length ? et(`${pend.length} itens sem resposta`, 'al') : ''}`,
      extra: `<div class="etapas" style="margin-top:12px">${ETAPAS.map(([s, n], j) => `<button type="button" class="${j < i ? 'feita' : j === i ? 'atual' : ''}" data-acao="etapaOS" data-id="${id}" data-s="${s}">${n}</button>`).join('')}</div>
        <div class="flex" style="margin-top:12px;flex-wrap:wrap">${prox ? `<button type="button" class="btn pri" data-acao="${prox[0] === 'orcamento' ? 'enviarOrc' : 'etapaOS'}" data-id="${id}" data-s="${prox[0]}">${ic(prox[2])}${prox[1]}</button>` : ''}${o.etapa === 'orcamento' ? `<button type="button" class="btn" data-acao="enviarOrc" data-id="${id}">${ic('whatsapp-logo')}Reenviar orçamento</button><button type="button" class="btn pri" data-acao="aprovarTudo" data-id="${id}">${ic('check')}Cliente aprovou tudo</button>` : ''}${o.etapa === 'servico' ? `<button type="button" class="btn" data-acao="aguardarPeca" data-id="${id}">${ic('hourglass')}Aguardando peça</button>` : ''}${o.etapa === 'pronto' ? `<button type="button" class="btn" data-acao="avisarPronto" data-id="${id}">${ic('whatsapp-logo')}Avisar cliente</button><button type="button" class="btn pri ok" data-acao="entregar" data-id="${id}">${ic('currency-circle-dollar')}Receber e entregar</button>` : ''}<button type="button" class="btn" data-acao="linkOS" data-id="${id}">${ic('link')}Link do cliente</button><button type="button" class="btn" data-acao="imprimirOS" data-id="${id}">${ic('printer')}Imprimir</button></div>`,
      aba, abas: [['itens', 'Orçamento', o.itens.length], ['fotos', 'Fotos', (o._anexos || []).length || ''], ['veiculo', 'Veículo e entrada'], ['hist', 'Histórico']], corpo,
      acoes: o.etapa !== 'entregue' ? `<button type="button" class="btn fant peq ic-so" data-acao="excluirOS" data-id="${id}" aria-label="Excluir">${ic('trash')}</button>` : '' }), montar: (g) => (g.dataset.aba = aba) };
  },
  veiculo(a, id) {
    const v = veic(a, id); if (!v) return null; const c = cli(a, v.cliente), os = ords(a).filter((o) => o.veiculo === id).sort((x, y) => y.entrada.localeCompare(x.entrada)), rv = revisaoVence(v);
    return { estreita: true, html: ficha({ tipo: 'Veículo', icone: 'car', titulo: `${esc(v.marca)} ${esc(v.modelo)}`, sub: `<span class="mono" style="font-weight:600">${esc(v.placa)}</span><span>${v.ano} · ${num(v.km)} km</span>${precisaRevisao(v) ? et('Revisão vencendo', 'al') : ''}`,
      extra: `<div class="flex" style="margin-top:12px"><button type="button" class="btn pri" data-acao="checkin" data-v="${id}">${ic('sign-in')}Dar entrada</button><button type="button" class="btn" data-acao="agendar" data-v="${id}">${ic('calendar-plus')}Agendar</button></div>`,
      corpo: `<div class="gav-sec">${props([['user', 'Dono', c ? `${esc(c.nome)} · <a href="${telLink(c.telefone)}" target="_blank" rel="noopener">WhatsApp</a>` : null], ['palette', 'Cor', esc(v.cor || '')], ['calendar-check', 'Última revisão', v.ultima_revisao ? `${dataCurta(v.ultima_revisao)} · ${num(v.km_revisao || 0)} km` : null], ['calendar-blank', 'Próxima revisão', rv ? `${dataCurta(rv.data)} ou ${num(rv.km)} km` : null], ['coins', 'Gasto na oficina', moeda(soma(os.filter((o) => o.etapa === 'entregue'), totalOS))]])}</div>
        <div class="gav-sec"><h4>Histórico de serviços (${os.length})</h4>${os.length ? `<ul class="lista" style="margin:0 -20px">${os.map((o) => `<li class="clicavel" data-abrir="os:${o.id}"><span class="mono mute-2">#${o.numero}</span><div class="cresce"><div class="t corta">${esc(valendo(o).filter((x) => x.tipo === 'servico').map((x) => x.descricao).join(', ') || o.relato)}</div><div class="s">${dataCurta(o.entrada)} · ${num(o.km)} km</div></div><b class="num">${moeda(totalOS(o))}</b></li>`).join('')}</ul>` : vazio('wrench', 'Nenhum serviço ainda')}</div>`,
      acoes: `<button type="button" class="btn fant peq" data-acao="editarCad" data-c="veiculos" data-id="${id}">${ic('pencil-simple')}Editar</button>` }) };
  },
};

